import 'package:flutter/cupertino.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Core/Utils/Extensions/responsive.dart';import '../../../../Config/Assets/images.dart';class AuthenticationSplit1 extends StatelessWidget {  const AuthenticationSplit1({super.key});  @override  Widget build(BuildContext context) {    final bool isSmall = context.isSmallScreen;    return Align(      alignment: isSmall ? Alignment.topCenter : Alignment.centerRight,      child: SizedBox(        width: isSmall ? null : 0.5.sw,        child: AspectRatio(          aspectRatio: 1,          child: Row(            children: [              _buildImageColumn(                  [AppImages.image9, AppImages.image8, AppImages.image7]),              _buildImageColumn(                  [AppImages.image4, AppImages.image6, AppImages.image5]),              _buildImageColumn(                  [AppImages.image3, AppImages.image2, AppImages.image1]),            ],          ),        ),      ),    );  }  Widget _buildImageColumn(List<String> imagePaths) {    return Expanded(      child: Column(        children: imagePaths.map((path) => _buildImage(path)).toList(),      ),    );  }  Widget _buildImage(String imagePath) {    return Expanded(      child: Image.asset(        imagePath,        fit: BoxFit.cover,      ),    );  }}